f8o/5Z/yT/mn/FP+L8r/AzeAs3AAyAAA
MAC_APP_PAYLOAD

# the theme
cp -r "$T/theme/usr/." /usr/
# the Themes app + the Amber theme (so you can always switch back)
python3 -c 'import PyQt5' 2>/dev/null || { echo "STATUS:Installing what the Themes app needs..."; apt-get install -y -q python3-pyqt5 >/dev/null 2>&1; }
cp -r "$T/app/usr/." /usr/
chmod 755 /usr/share/mikeos-amber/bin/amber-themes
chmod -R a+rX /usr/share/mikeos-amber/themes /usr/share/lxqt/themes/mac-style /usr/share/themes/Mac-Style /usr/share/wallpapers/MikeOS-Mac-Style 2>/dev/null

# full desktop (KDE): a taskbar style in white and grey, made from the standard one
if [ -d /usr/share/plasma/desktoptheme/default ]; then
    D=/usr/share/plasma/desktoptheme/mikeos-mac-style
    rm -rf "$D"; cp -r /usr/share/plasma/desktoptheme/default "$D"
    rm -f "$D/metadata.desktop"
    cat > "$D/metadata.json" <<'META'
{ "KPlugin": { "Id": "mikeos-mac-style", "Name": "Mac Style", "Description": "Mike OS Mac Style taskbar",
  "Authors": [ { "Name": "Mike OS" } ], "License": "LGPL", "Version": "1.0" },
  "X-Plasma-API": "5.0" }
META
    cp /usr/share/mikeos-amber/themes/mac-style/plasma-colors "$D/colors"
fi
command -v update-desktop-database >/dev/null && update-desktop-database -q /usr/share/applications || true
rm -rf "$T"

# already using Mac Style (an update)? refresh it so the new dock shows up
mapfile -t envs < <(desktop_env)
if [ "$(cat "$USER_HOME/.config/mikeos-amber/theme" 2>/dev/null)" = mac-style ]; then
    echo "STATUS:Refreshing Mac Style..."
    sudo -u "$USER_NAME" env HOME="$USER_HOME" "${envs[@]}" python3 /usr/share/mikeos-amber/apps/themes.py --apply mac-style \
        >/dev/null 2>&1 < /dev/null || true
    echo "Mac Style updated."
    exit 0
fi
# open the Themes app so Mac Style can be switched on
if [ ${#envs[@]} -gt 0 ]; then
    sudo -u "$USER_NAME" env HOME="$USER_HOME" "${envs[@]}" setsid python3 /usr/share/mikeos-amber/apps/themes.py >/dev/null 2>&1 < /dev/null &
fi
echo "Mac Style installed - turn it on in the Themes app (start menu > Preferences > Themes)."
